// Popup 日志面板
// 职责：展示/过滤/导出日志，切换日志等级（纯 UI，不直接碰 storage）
// 所有数据通过消息从 background 获取（background 是日志唯一写入者）

import { initLogger } from '../lib/logger'
import { sendMessage } from '../lib/messages'
import type { LogEntry, LogLevel } from '../lib/types'

const logger = initLogger('popup')

// ---------- DOM 引用 ----------
const levelSelect = document.getElementById('level-select') as HTMLSelectElement
const logList = document.getElementById('log-list') as HTMLElement
const emptyTip = document.getElementById('empty-tip') as HTMLElement
const logCount = document.getElementById('log-count') as HTMLElement
const btnRefresh = document.getElementById('btn-refresh') as HTMLButtonElement
const btnClear = document.getElementById('btn-clear') as HTMLButtonElement
const btnCopy = document.getElementById('btn-copy') as HTMLButtonElement
const btnExport = document.getElementById('btn-export') as HTMLButtonElement
const versionEl = document.getElementById('app-version') as HTMLElement

let allEntries: LogEntry[] = []
let currentFilter: 'all' | LogLevel = 'all'

// ---------- 渲染 ----------
function formatTime(ts: number): string {
  const d = new Date(ts)
  const pad = (n: number) => String(n).padStart(2, '0')
  return `${pad(d.getHours())}:${pad(d.getMinutes())}:${pad(d.getSeconds())}.${String(d.getMilliseconds()).padStart(3, '0')}`
}

function render() {
  const shown = currentFilter === 'all' ? allEntries : allEntries.filter((e) => e.level === currentFilter)
  logList.innerHTML = ''

  for (const entry of shown) {
    const row = document.createElement('div')
    row.className = 'log-entry'

    const tsSpan = document.createElement('span')
    tsSpan.className = 'ts'
    tsSpan.textContent = formatTime(entry.ts)

    const levelSpan = document.createElement('span')
    levelSpan.className = `level ${entry.level}`
    levelSpan.textContent = entry.level

    const ctxSpan = document.createElement('span')
    ctxSpan.className = 'ctx'
    ctxSpan.textContent = `[${entry.context}/${entry.module}]`

    const msgSpan = document.createElement('span')
    msgSpan.className = 'msg'
    msgSpan.textContent = entry.message

    row.append(tsSpan, levelSpan, ctxSpan, msgSpan)

    if (entry.data !== undefined) {
      const dataDiv = document.createElement('div')
      dataDiv.className = 'data'
      dataDiv.textContent = safeStringify(entry.data)
      row.appendChild(dataDiv)
    }

    logList.appendChild(row)
  }

  emptyTip.classList.toggle('show', shown.length === 0)
  logCount.textContent = `${shown.length} / ${allEntries.length} 条`
}

function safeStringify(value: unknown): string {
  try {
    return JSON.stringify(value, null, 2)
  } catch {
    return String(value)
  }
}

// ---------- 数据加载 ----------
async function loadLogs(): Promise<void> {
  const res = await sendMessage<{ ok: true; entries: LogEntry[] } | { ok: false; error: string }>({ type: 'LOG_GET' })
  if (res.ok) {
    allEntries = res.entries
    render()
  } else {
    logger.error('popup', '拉取日志失败', res.error)
  }
}

async function loadLevel(): Promise<void> {
  const res = await sendMessage<{ ok: true; level: LogLevel } | { ok: false; error: string }>({ type: 'LOG_GET_LEVEL' })
  if (res.ok) {
    levelSelect.value = res.level
  }
}

// ---------- 导出 / 复制 ----------
function buildExportText(): string {
  const header = `# 插件日志导出\n# 时间: ${new Date().toLocaleString()}\n# 版本: ${chrome.runtime.getManifest().version}\n# 条数: ${allEntries.length}\n\n`
  const lines = allEntries.map((e) => {
    const time = new Date(e.ts).toLocaleString('zh-CN', { hour12: false })
    const data = e.data !== undefined ? ` ${safeStringify(e.data)}` : ''
    return `[${time}] [${e.level}] [${e.context}/${e.module}] ${e.message}${data}`
  })
  return header + lines.join('\n')
}

async function copyLogs(): Promise<void> {
  const text = buildExportText()
  try {
    await navigator.clipboard.writeText(text)
    logger.info('popup', '日志已复制到剪贴板')
  } catch {
    // clipboard API 在部分环境不可用，降级 textarea
    const ta = document.createElement('textarea')
    ta.value = text
    document.body.appendChild(ta)
    ta.select()
    document.execCommand('copy')
    ta.remove()
    logger.info('popup', '日志已复制到剪贴板（降级方式）')
  }
}

function exportLogs(): void {
  const blob = new Blob([buildExportText()], { type: 'text/plain;charset=utf-8' })
  const url = URL.createObjectURL(blob)
  const a = document.createElement('a')
  a.href = url
  a.download = `extension-log-${Date.now()}.log`
  a.click()
  URL.revokeObjectURL(url)
  logger.info('popup', '日志已导出为文件')
}

// ---------- 事件绑定 ----------
levelSelect.addEventListener('change', async () => {
  const level = levelSelect.value as LogLevel
  const res = await sendMessage({ type: 'LOG_SET_LEVEL', level })
  if (res.ok) {
    logger.info('popup', `日志等级切换为 ${level}`)
    void loadLogs()
  }
})

document.querySelectorAll<HTMLButtonElement>('.chip').forEach((chip) => {
  chip.addEventListener('click', () => {
    document.querySelectorAll('.chip').forEach((c) => c.classList.remove('active'))
    chip.classList.add('active')
    currentFilter = chip.dataset.filter as 'all' | LogLevel
    render()
  })
})

btnRefresh.addEventListener('click', () => {
  void loadLogs()
})

btnClear.addEventListener('click', async () => {
  const res = await sendMessage({ type: 'LOG_CLEAR' })
  if (res.ok) {
    allEntries = []
    render()
    logger.info('popup', '日志已清空')
  }
})

btnCopy.addEventListener('click', () => {
  void copyLogs()
})

btnExport.addEventListener('click', () => {
  exportLogs()
})

// ---------- 初始化 ----------
void (async () => {
  versionEl.textContent = `v${chrome.runtime.getManifest().version}`
  await loadLevel()
  await loadLogs()
  logger.info('popup', 'popup 面板打开')
})()
