// 共享类型定义（schema 单一来源）

/** 日志等级 */
export type LogLevel = 'debug' | 'info' | 'warn' | 'error'

/** 日志来源上下文 */
export type LogContext = 'background' | 'content' | 'popup'

/** 单条日志条目 */
export interface LogEntry {
  id: number
  ts: number
  context: LogContext
  level: LogLevel
  module: string
  message: string
  data?: unknown
}

/** 等级数值（用于比较过滤） */
export const LEVEL_ORDER: Record<LogLevel, number> = {
  debug: 10,
  info: 20,
  warn: 30,
  error: 40,
}
